const $=id=>document.getElementById(id);const data={past:[{q:'Before your current role, you ___ as a social worker.',choices:['work','worked','have work'],answer:'worked',hint:'Past simple: the completed earlier profession takes a regular -ed form.',why:'Worked is past simple. The earlier career is a completed stage.'},{q:'Did you ___ with families?',choices:['worked','work','working'],answer:'work',hint:'After DID, always use the base verb.',why:'Did + subject + base verb.'},{q:'I ___ people in difficult situations in my former job.',choices:['helped','helps','help'],answer:'helped',hint:'This is a past, finished period.',why:'Helped: regular past simple.'},{q:'I ___ to support my son at a running race recently.',choices:['go','went','have go'],answer:'went',hint:'A completed outing takes the past simple of go.',why:'Went is the irregular past of go.'}],present:[{q:'I currently ___ as an assessor.',choices:['serve','served','serves'],answer:'serve',hint:'I + base form for a current role.',why:'Present simple with I takes serve.'},{q:'An assessor ___ part in hearings.',choices:['take','takes','taking'],answer:'takes',hint:'Third-person singular he/she/it needs -s.',why:'An assessor = he or she → takes.'},{q:'___ you regularly attend hearings?',choices:['Do','Did','Does'],answer:'Do',hint:'Current habit + you → Do.',why:'Do + you + base verb for present simple questions.'},{q:'I ___ share private details about individual cases.',choices:['does not','do not','not'],answer:'do not',hint:'Present simple negative: I + do not + base verb.',why:'I do not share is a correct present simple negative.'}],used:[{q:'I ___ be a social worker, but now I serve as an assessor.',choices:['used to','use to','am used to'],answer:'used to',hint:'Affirmative habit/state in the past: used to + base verb.',why:'Used to describes a former state that has changed.'},{q:'Did you ___ work with families?',choices:['used to','use to','using to'],answer:'use to',hint:'Did already marks past; remove the -d.',why:'Did + subject + use to + base verb.'},{q:'I am used to ___ to people in difficult situations.',choices:['listen','listening','listened'],answer:'listening',hint:'Be used to = accustomed to + noun / -ing.',why:'Be used to listening means being accustomed to it.'}],perfect:[{q:'I ___ gained experience supporting young people.',choices:['have','has','did'],answer:'have',hint:'Present perfect with I: have + past participle.',why:'I have gained expresses accumulated experience relevant now.'},{q:'I have ___ retired for one year.',choices:['be','been','was'],answer:'been',hint:'Present perfect: have + past participle of be.',why:'Have been retired for one year = a situation continuing now.'},{q:'She has ___ many hearings.',choices:['attend','attended','attends'],answer:'attended',hint:'Has + V3 (past participle).',why:'She has attended is present perfect.'},{q:'I ___ as a social worker several years ago.',choices:['worked','have worked','work'],answer:'worked',hint:'A specific finished period → past simple.',why:'The finished time phrase calls for past simple, not present perfect.'}],responsibility:[{"q": "I need ___ carefully to families.", "choices": ["listen", "to listen", "listening"], "answer": "to listen", "hint": "Need + to + base verb.", "why": "Need to listen describes a responsibility."}, {"q": "I ___ have to make every decision alone.", "choices": ["don’t", "doesn’t", "not"], "answer": "don’t", "hint": "With I, use do not / don’t.", "why": "Don’t have to means not necessary."}],involve:[{"q": "My role involves ___ carefully.", "choices": ["to listen", "listening", "listen"], "answer": "listening", "hint": "Involve + -ing.", "why": "Involves listening is the correct pattern."}, {"q": "My previous career helped me ___ empathy.", "choices": ["develop", "developing", "developed"], "answer": "develop", "hint": "Helped me + base verb.", "why": "Helped me develop empathy is correct."}],reasons:[{"q": "My coach moved me up ___ I made progress.", "choices": ["because of", "because", "so"], "answer": "because", "hint": "Followed by subject + verb → because.", "why": "Because I made progress uses a full clause."}, {"q": "I moved to a higher-level group because of my ___.", "choices": ["improve", "improved", "progress"], "answer": "progress", "hint": "Because of + noun.", "why": "Progress is a noun."}],achievement:[{"q": "My coach recently ___ me into a new group.", "choices": ["moved", "move", "moving"], "answer": "moved", "hint": "Describe a completed decision in the past.", "why": "Moved is the past simple."}, {"q": "I have ___ my endurance.", "choices": ["improve", "improved", "improving"], "answer": "improved", "hint": "Have + past participle.", "why": "Have improved refers to progress that matters now."}],family:[{"q": "I went to ___ on my son at a race.", "choices": ["cheer", "cheered", "cheering"], "answer": "cheer", "hint": "To + base verb describes purpose.", "why": "To cheer on means to support and encourage."}, {"q": "My coach, ___ knows my abilities, moved me up.", "choices": ["which", "who", "where"], "answer": "who", "hint": "Use a relative pronoun for a person.", "why": "Who refers to a person."}]};
