const scenarios=[{"name": "Introduce yourself", "question": "Could you introduce yourself and tell me a little about your life?", "words": "Claye-Souilly · retired · used to · assessor · running", "steps": ["Say where you live.", "Explain that you are retired and name your earlier career.", "Describe your current volunteer role.", "Add a genuine interest or your running achievements."], "hint": "I live in… / I used to… / I have been retired for… / I currently volunteer… / In my free time…", "a2": "I live in Claye-Souilly. I used to be a social worker. I am now retired, and I volunteer as an assessor in youth justice. I enjoy walking, running and travelling with my husband.", "b1": "I live in Claye-Souilly. Earlier in my career, I worked as a social worker, supporting young people and families in difficult situations. I have been retired for a year, but I currently volunteer as an assessor in youth justice. My background helps me listen carefully and understand different needs. I also enjoy walking in nature, travelling with my husband and running regularly."}, {"name": "Explain your former career", "question": "What did you do as a social worker?", "words": "young people · families · needs · judge · empathy · teamwork", "steps": ["Introduce the past role.", "Describe supporting young people and families.", "Explain careful listening, patience and empathy.", "Mention explaining situations to a judge and working with a team, in general terms."], "hint": "I worked as… / I supported… / My role involved… / Teamwork mattered because…", "a2": "I worked as a social worker. I supported people and listened to their problems. The job taught me to be patient.", "b1": "In my previous career, I worked as a social worker supporting young people and families. The role involved listening carefully, understanding their needs and helping to explain family situations and possible actions to a judge. I developed empathy, patience and communication skills. It was important to work as part of a team rather than alone."}, {"name": "Describe your present volunteer role", "question": "What do you do now that you are retired?", "words": "retired · assessor · youth justice · listen · understand needs", "steps": ["Say that you are retired from your former career.", "Give your volunteer role accurately.", "Say what the work requires.", "Connect it with skills gained as a social worker."], "hint": "I am retired… / I volunteer as… / I need to… / This draws on…", "a2": "I am now retired. I volunteer as an assessor in youth justice. I need to listen carefully and understand different needs.", "b1": "Although I am retired from my previous career, I currently volunteer as an assessor in youth justice. This work draws on my experience of listening carefully, understanding different needs and communicating with empathy. I find it important to work as part of a team."}, {"name": "Talk about running progress", "question": "What sports or physical activities do you enjoy?", "words": "regularly · coach · progress · higher-level running group · endurance", "steps": ["Say that you run regularly.", "Explain that your results have improved.", "Describe the move your coach made to a more advanced group.", "Say how it feels or what keeps you motivated."], "hint": "I regularly… / My coach recently… / Because of my progress… / I feel…", "a2": "I run regularly. I have improved a lot. My coach recently moved me into a more advanced running group. I am proud of my progress.", "b1": "Running is an important part of my life. I train regularly and have made good progress, particularly for my age group. Because of my results, my coach recently moved me into a higher-level training group. It is motivating to see how much my endurance has improved."}, {"name": "Talk about family races", "question": "Does your family share your interest in sport?", "words": "children · races · cheer on · son · family members", "steps": ["Explain that your children take part in different running races.", "Describe one recent event you attended.", "Use the past simple for the finished outing.", "Explain why supporting each other matters to you."], "hint": "My children… / Recently, I went to… / I cheered on… / I enjoyed…", "a2": "My children take part in different running races. Recently, I went to watch my son and other family members run. I enjoyed cheering them on.", "b1": "Running is something my family shares. My children participate in different kinds of races, and I enjoy supporting them. Recently, I went to watch my son and other relatives compete, and it was a pleasure to cheer them on and spend time together."}, {"name": "Compare past and present", "question": "How has your life changed since you retired?", "words": "used to · now · whereas · experience · although", "steps": ["Describe your old career.", "Use whereas, but or now to introduce a contrast.", "Explain your volunteer responsibilities.", "Mention an activity that gives you satisfaction today."], "hint": "I used to… whereas now… / Although I am retired… / Both roles involve…", "a2": "I used to work as a social worker. Now I am retired, but I volunteer in youth justice. I also have time for running and travelling.", "b1": "I used to work in social services, whereas I now volunteer as an assessor in youth justice. Although my daily routine has changed since retirement, I still use the empathy, patience and communication skills I developed in my career. I also enjoy having time for running and travelling."}, {"name": "Talk about a holiday", "question": "Could you describe a memorable trip you took?", "words": "Croatia · Dubrovnik · Mljet · Montenegro · scenery", "steps": ["Name one actual destination.", "Say when you travelled, if you remember.", "Describe what you saw or enjoyed, without inventing events.", "Explain why it was memorable."], "hint": "I travelled to… / I visited… / What I enjoyed most was…", "a2": "I travelled to Croatia and Montenegro with my husband. We visited beautiful places and enjoyed the scenery. I particularly like walking in nature.", "b1": "One memorable holiday was our trip to Croatia and Montenegro. I was interested in places such as Dubrovnik, Mljet, the Bay of Kotor and Durmitor. I especially enjoy destinations that combine historical towns, coastal scenery and opportunities to walk in nature."}, {"name": "Handle a sensitive situation", "question": "What qualities are important when working with young people and families?", "words": "empathy · confidentiality · teamwork · patience", "steps": ["Name two qualities.", "Explain why they matter.", "Give a general illustrative example, without sharing real cases.", "Conclude by mentioning teamwork and confidentiality."], "hint": "I believe… is essential because… / For example… / It is also important to…", "a2": "I think patience and empathy are important. We must listen carefully and work as a team. We must also respect confidentiality.", "b1": "I believe that empathy, patience and careful listening are essential when working with young people and families. It is important to understand individual circumstances without making assumptions. Teamwork and confidentiality also matter because sensitive situations should never be handled carelessly."}];
let progress={},mockIndex=0,secs=60,timer=null;function speak(t){if(!('speechSynthesis' in window)){alert('Speech is not available in this browser.');return;}speechSynthesis.cancel();const u=new SpeechSynthesisUtterance(t);u.lang=$('audioAccent')?.value||'en-GB';u.rate=.88;speechSynthesis.speak(u)}function note(t){$('status').textContent=t;setTimeout(()=>{if($('status').textContent===t)$('status').textContent=''},3000)}function esc(s){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function introduction(){const town=$('town').value.trim()||'Claye-Souilly';const location=/^(i\s|we\s)/i.test(town)?town.replace(/[.]+$/,'')+'.':'I live in '+town.replace(/[.]+$/,'')+'.';const role=$('role').value;const interest=$('interest').value;const running=$('includeRunning').checked?' I run regularly, and my coach recently moved me into a higher-level group because of my progress. My children take part in running races, and I enjoy cheering them on.':'';return $('introLevel').value==='a2'?`${location} I used to be a social worker. I am now retired. ${role} ${interest}${running}`:`${location} Earlier in my career, I worked as a social worker, supporting young people and families in difficult situations. I have been retired for a year, but ${role.charAt(0).toLowerCase()+role.slice(1)} My previous career helped me develop empathy and patience. This work draws on my experience of listening carefully and understanding different needs. ${interest}${running}`;}function buildIntro(){$('introOutput').textContent=introduction()}
function exerciseUI(){document.querySelectorAll('.exercises').forEach(target=>{const g=target.dataset.group;target.innerHTML=data[g].map((e,i)=>`<div class="exercise" data-key="${g}-${i}"><h3>${i+1}. ${esc(e.q)}</h3><div class="choices">${e.choices.map(c=>`<button type="button" data-choice="${esc(c)}">${esc(c)}</button>`).join('')}</div><div class="actions"><button class="secondary" data-hint="1">💡 Hint</button><button class="secondary" data-reset="1">Try again</button></div><div class="feedback" aria-live="polite"></div><div class="hint" hidden></div></div>`).join('')})}function renderScore(){const all=Object.values(data).flat().length;const correct=Object.values(progress).filter(x=>x.correct).length;const tried=Object.keys(progress).length;$('scoreboard').textContent=`${correct} / ${all} correct · ${tried} attempted. Categories: `+Object.keys(data).map(k=>{const done=data[k].filter((_,i)=>progress[k+'-'+i]?.correct).length;return k+': '+done+'/'+data[k].length}).join(' · ')}function examMode(){const exam=$('mode').value==='exam';document.querySelectorAll('[data-hint]').forEach(b=>b.disabled=exam);$('mockHint').disabled=exam;note(exam?'Independent mode: hints disabled.':'Guided mode: hints available.')}document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;const ex=b.closest('.exercise');if(!ex)return;const [g,i]=ex.dataset.key.split('-');const item=data[g][+i],feed=ex.querySelector('.feedback');if(b.hasAttribute('data-choice')){let selected=b.dataset.choice,ok=selected===item.answer;ex.querySelectorAll('[data-choice]').forEach(v=>v.classList.toggle('chosen',v===b));feed.className='feedback '+(ok?'good':'bad');feed.textContent=ok?'✓ Correct! '+item.why:'✗ Not quite. '+( $('mode').value==='practice'?item.why:'Try again or switch back to guided mode.');progress[ex.dataset.key]={correct:ok,selected};renderScore()}else if(b.hasAttribute('data-hint')){const h=ex.querySelector('.hint');h.hidden=!h.hidden;h.textContent='Hint: '+item.hint}else if(b.hasAttribute('data-reset')){ex.querySelectorAll('.chosen').forEach(x=>x.classList.remove('chosen'));feed.textContent='';feed.className='feedback';ex.querySelector('.hint').hidden=true;delete progress[ex.dataset.key];renderScore()}});
function vocabulary(){const a=vocab[$('vocabTopic').value];$('vocabList').innerHTML=a.map((w,i)=>`<div class="word"><div class="vocab-info"><b>${esc(w[0])}</b><p><strong>FR:</strong> ${esc(w[1])}</p><p><strong>Definition:</strong> ${esc(w[2])}</p><p><strong>Example:</strong> ${esc(w[3])}</p></div><div class="vocab-buttons"><button type="button" class="secondary" data-word="${i}" aria-label="Listen to ${esc(w[0])}">🔊 Word</button><button type="button" class="secondary" data-example="${i}" aria-label="Listen to example">🔊 Sentence</button></div></div>`).join('')}
function scenario(){const s=scenarios[+$('scenario').value];$('scenarioContent').innerHTML=`<div class="scenario-box"><div class="kicker">COACHING → INDEPENDENCE</div><h3>${esc(s.question)}</h3><p><b>Words to use:</b> ${esc(s.words)}</p><h4>Step-by-step plan</h4><ol>${s.steps.map(x=>'<li>'+esc(x)+'</li>').join('')}</ol><div class="actions"><button type="button" id="scenarioHint" class="secondary">Show sentence starter</button><button type="button" id="scenarioA2" class="secondary">A2 model</button><button type="button" id="scenarioB1" class="secondary">B1 model</button><button type="button" id="scenarioSpeak" class="secondary">🔊 Hear question</button></div><div id="scenarioReveal" class="model" hidden></div><label>Now answer in your own words<textarea id="scenarioAnswer" rows="4" placeholder="Write notes here or answer aloud without reading..."></textarea></label></div>`}function setReveal(t){$('scenarioReveal').textContent=t;$('scenarioReveal').hidden=false}
function mock(){const s=scenarios[mockIndex];$('mockCount').textContent=`Question ${mockIndex+1} / ${scenarios.length}`;$('mockQuestion').textContent=s.question;$('mockHelp').textContent='';$('mockHelp').className='feedback';$('mockAnswer').value=''}function stopClock(){clearInterval(timer);timer=null}function renderClock(){$('clock').textContent=String(Math.floor(secs/60)).padStart(2,'0')+':'+String(secs%60).padStart(2,'0')}function startClock(){stopClock();secs=60;renderClock();timer=setInterval(()=>{secs=Math.max(0,secs-1);renderClock();if(!secs){stopClock();note('Time is up — finish your answer and review it.')}},1000)}function exportNotes(){const rows=['CATHERINE — CLOE ORAL INTERVIEW — PRACTICE NOTES','', 'PERSONAL INTRODUCTION',introduction(),'','GRAMMAR RESULTS',...Object.keys(data).flatMap(k=>data[k].map((x,i)=>{const p=progress[`${k}-${i}`];return `${k.toUpperCase()} — ${x.q} | ${p?(p.correct?'CORRECT':'REVIEW')+' ('+p.selected+')':'not attempted'} | Answer: ${x.answer}`})),'','CURRENT SCENARIO',scenarios[+$('scenario').value].question,$('scenarioAnswer')?.value||'','', 'SIMULATION',scenarios[mockIndex].question,$('mockAnswer').value,'','REFLECTION',$('reflection').value,'','NEXT TARGET',$('target').value];const blob=new Blob([rows.join('\n')],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Catherine_CLOE_oral_practice_notes.txt';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function bind(){exerciseUI();renderScore();$('buildIntro').onclick=buildIntro;$('listenIntro').onclick=()=>speak($('introOutput').textContent);$('readPage').onclick=()=>speak(introduction());$('copyIntro').onclick=()=>navigator.clipboard?.writeText($('introOutput').textContent).then(()=>note('Introduction copied.'),()=>note('Copy not supported in this browser.'));$('mode').onchange=examMode;$('vocabTopic').onchange=vocabulary;$('vocabList').onclick=e=>{const b=e.target.closest('[data-word]');if(b)speak(vocab[$('vocabTopic').value][+b.dataset.word][0]);const x=e.target.closest('[data-example]');if(x)speak(vocab[$('vocabTopic').value][+x.dataset.example][3])};$('scenario').innerHTML=scenarios.map((s,i)=>`<option value="${i}">${i+1}. ${esc(s.name)}</option>`).join('');$('scenario').onchange=scenario;$('scenarioContent').onclick=e=>{const s=scenarios[+$('scenario').value],id=e.target.id;if(id==='scenarioHint'){if($('mode').value==='practice')setReveal('Starter: '+s.hint);else note('Switch to guided practice to see hints.')}if(id==='scenarioA2')setReveal('A2 MODEL\n'+s.a2);if(id==='scenarioB1')setReveal('B1 MODEL\n'+s.b1);if(id==='scenarioSpeak')speak(s.question)};$('speakQuestion').onclick=()=>speak(scenarios[mockIndex].question);$('startClock').onclick=startClock;$('stopClock').onclick=stopClock;$('nextQuestion').onclick=()=>{stopClock();secs=60;renderClock();mockIndex=(mockIndex+1)%scenarios.length;mock()};$('mockHint').onclick=()=>{$('mockHelp').textContent='Starter: '+scenarios[mockIndex].hint};$('mockModels').onclick=()=>{$('mockHelp').textContent='A2 MODEL\n'+scenarios[mockIndex].a2+'\n\nB1 MODEL\n'+scenarios[mockIndex].b1;$('mockHelp').style.whiteSpace='pre-line'};$('exportNotes').onclick=exportNotes;$('downloadTop').onclick=exportNotes;$('resetAll').onclick=()=>{if(!confirm('Reset all corrected grammar answers and scores?'))return;progress={};exerciseUI();renderScore();note('Practice reset.')};document.querySelectorAll('.sidebar a').forEach(a=>a.addEventListener('click',()=>{document.querySelectorAll('.sidebar a').forEach(x=>x.classList.remove('active'));a.classList.add('active')}));buildIntro();vocabulary();scenario();mock();renderClock();examMode()}
