const ORAL_ROLEPLAYS = [{"title": "Welcome a visitor to a youth justice service", "area": "Professional greeting · neutral and courteous", "context": "You welcome a parent arriving for an appointment. The examiner plays the visitor.", "prep": ["Hello, how can I help you?", "Do you have an appointment?", "Please take a seat. I will check."], "turns": [["Hello. I am here for a meeting, but I am not sure where to go.", "Of course. How can I help you?", "Go anywhere.", "You are wrong.", 0, "A polite greeting and a question help you understand the need.", "Start with Of course / Certainly, then ask how you can help.", "Of course. How can I help you?", "Of course. May I ask who you are here to see so I can direct you to the right place?"], ["My appointment is at ten, but I do not know which room.", "Let me check where your meeting is taking place.", "I do not want to check.", "Come back tomorrow.", 0, "Offer to verify instead of guessing.", "Say Let me check…", "Let me check the room for you.", "Let me check the appointment details so that I can give you accurate directions."], ["Thank you. Can I wait here?", "Yes, please take a seat. I will let you know.", "No, you should stand.", "I do not care.", 0, "Confirm what happens next, with polite language.", "Use Please take a seat…", "Yes, please take a seat.", "Yes, please take a seat here. I will let you know as soon as the room is ready."]]}, {"title": "A worried parent asks for help", "area": "Active listening · empathy", "context": "A parent is worried. You listen without making promises about a legal outcome.", "prep": ["I understand that this is difficult.", "Could you tell me a little more?", "We can discuss possible next steps."], "turns": [["I am very worried about my child.", "I understand. Would you like to explain what is worrying you?", "Do not worry. It is nothing.", "That is not my problem.", 0, "Show empathy and invite explanation.", "Acknowledge feeling, then ask an open question.", "I understand. Please tell me more.", "I can understand why you are concerned. Could you explain what has happened so we can understand the situation better?"], ["I do not know what to do next.", "We can look at the options together.", "You must do exactly what I say.", "I guarantee everything will be fine.", 0, "Offer support without promising an outcome.", "Try We can… together.", "We can look at options together.", "We can discuss the available options and identify a suitable next step together."], ["Can you decide everything today?", "I cannot promise a decision today, but I can explain the process.", "Yes, I will guarantee a decision.", "I will not tell you anything.", 0, "Avoid guarantees; explain the process in general terms.", "Use I cannot promise…, but I can…", "I cannot promise that. I can explain the process.", "I cannot promise when a decision will be made, but I can explain the next stages and whom to contact."]]}, {"title": "Arrange or change an appointment", "area": "Dates · clarification · polite requests", "context": "The examiner plays a colleague who needs to reschedule a meeting.", "prep": ["Would another time be possible?", "Could you repeat the date, please?", "Let me confirm the details."], "turns": [["I cannot come on Thursday. Can we change the meeting?", "Of course. Would Friday be possible?", "Thursday is compulsory.", "You must cancel everything.", 0, "Acknowledge and suggest an alternative.", "Say Of course and offer another day.", "Would Friday be possible?", "Of course. We can look for another suitable time. Would Friday morning work for you?"], ["Friday afternoon is better.", "That should be possible. Let me check the schedule.", "Afternoon is a bad word.", "I will not check.", 0, "Confirm without inventing availability.", "Let me check…", "Let me check Friday afternoon.", "Thank you. Let me check availability for Friday afternoon before we confirm."], ["What time is my meeting now?", "I will confirm the exact time once it has been arranged.", "It is definitely at three, I think.", "I do not remember and will not check.", 0, "Never invent exact meeting times.", "Use confirm and exact time.", "I will confirm the time.", "I will send you confirmation of the exact time once the appointment is arranged."]]}, {"title": "Explain your former responsibilities", "area": "Past simple · explaining a process", "context": "An examiner asks you to describe how you supported families in your previous career.", "prep": ["I used to visit families at home.", "I listened to parents and children.", "We worked as a team to develop an action plan."], "turns": [["What was your main responsibility?", "My main responsibility was to protect children and support families.", "My main responsibility is yesterday.", "I protected all children alone.", 0, "Use was for your former job.", "Main responsibility was…", "I supported families and protected children.", "My main responsibility was to protect children and support families experiencing difficulties."], ["How did you understand what the families needed?", "I visited families and listened carefully to parents and children.", "I listen yesterday to family.", "I already knew without asking.", 0, "Use past simple for actual former tasks.", "Visited / listened to…", "I visited families and listened to them.", "I carried out home visits and spoke with both parents and children to understand their needs."], ["What happened after those visits?", "My team discussed possible solutions and developed an action plan.", "I discussed about the problem myself alone.", "I always made the judge decide immediately.", 0, "Teamwork and discuss something (no about).", "We discussed… and developed…", "We discussed solutions and made a plan.", "We worked together to discuss each case and develop an action plan suited to the family’s needs."]]}, {"title": "A visitor asks for confidential details", "area": "Professional boundaries · tact", "context": "Someone asks for private information about an individual family or child. Do not reveal details.", "prep": ["I am sorry, but that information is confidential.", "I cannot share details of an individual case.", "I can explain the general procedure."], "turns": [["Can you tell me exactly what happened to that family?", "I am sorry, but I cannot share confidential details.", "Yes. I will tell you everything.", "I will post the details online.", 0, "Confidentiality is essential.", "I am sorry, but I cannot share…", "I cannot share private information.", "I understand your question, but I am not able to discuss confidential information about an individual family."], ["But I am curious. Why not?", "We have to respect people’s privacy.", "Because I dislike you.", "The rules do not matter.", 0, "Explain the principle simply and respectfully.", "We must respect…", "We must respect privacy.", "Our responsibility is to protect privacy and follow confidentiality requirements."], ["Can you explain the system more generally?", "Yes, I can explain the general process without identifying anyone.", "No, all questions are forbidden.", "Yes, I will name the family.", 0, "Offer a safe alternative.", "I can explain the general…", "Yes, I can explain the general process.", "Certainly. I can describe how the general process works, without discussing any identifiable person or case."]]}, {"title": "A colleague disagrees about a plan", "area": "Diplomatic disagreement · teamwork", "context": "A colleague questions a proposed action plan. Practise polite disagreement and collaboration.", "prep": ["I understand your point.", "Could we discuss another option?", "We should consider the family’s needs."], "turns": [["I do not think this is the best solution.", "I understand your point. Could we discuss another option?", "You are completely wrong.", "I refuse to listen.", 0, "Acknowledge, then propose a discussion.", "I understand…, but could we…?", "We can discuss another option.", "I see your point. Perhaps we could review the options together before making a recommendation."], ["What should we focus on first?", "We should focus on the child’s needs and safety.", "We should choose the fastest answer only.", "We should ignore the family.", 0, "Use should + base verb.", "We should + verb…", "We should focus on the child’s needs.", "I think we should focus on the child’s safety, the family’s needs and the information available."], ["How can we reach an agreement?", "Let us compare the options and agree on the next step.", "Only my opinion matters.", "We cannot work together.", 0, "Offer a practical collaborative next step.", "Let us…", "Let us discuss the options.", "Let us compare the possible actions and work together to agree on the most appropriate next step."]]}, {"title": "Explain a problem with a video call", "area": "Clarification · communication repair", "context": "Your online discussion starts, but you cannot hear the examiner clearly.", "prep": ["I am sorry, I cannot hear you clearly.", "Could you repeat the question, please?", "Could you speak a little more slowly?"], "turns": [["Can you hear me?", "Yes, I can hear you now.", "I hearing you.", "I can listening you.", 0, "Use can + base verb.", "I can hear…", "Yes, I can hear you.", "Yes, I can hear you clearly now. Thank you for checking."], ["I will explain the situation quickly...", "I am sorry, could you repeat that more slowly, please?", "You speak wrong.", "Repeat !", 0, "Polite clarification is a useful exam skill.", "Could you repeat…?", "Could you repeat that, please?", "I am sorry, I missed part of the question. Could you repeat it a little more slowly, please?"], ["Do you understand what I am asking?", "I think so. You are asking me to describe my previous role, is that right?", "I do not need to listen.", "Yes, but I will not answer.", 0, "Paraphrase to check understanding.", "You are asking me to…, is that right?", "You want me to describe my work, right?", "Yes, I believe you would like me to explain my former responsibilities and give an example. Is that correct?"]]}, {"title": "Hotel request during a trip", "area": "Everyday service interaction · travel", "context": "You are travelling with your husband. The examiner plays the hotel receptionist.", "prep": ["We have a reservation under…", "Could we have a quieter room, please?", "Could you confirm the check-out time?"], "turns": [["Good afternoon. How can I help you?", "Hello. We have a reservation for two people.", "Me reservation two.", "We is reservation.", 0, "Use have a reservation.", "We have a reservation…", "We have a reservation for two.", "Good afternoon. My husband and I have a reservation for two nights. Could you help us check in, please?"], ["Would you like anything else?", "Could we have a quiet room, if possible?", "Quiet room give.", "I am quiet please room.", 0, "Polite request: Could we have…?", "Could we… please?", "A quiet room, please.", "If one is available, could we possibly have a quiet room away from the lift?"], ["Of course. Is there anything you would like to know?", "Could you tell us what time check-out is?", "Check-out how the time?", "You must tell check-out time.", 0, "Indirect question: what time check-out is.", "Could you tell us…?", "What time is check-out?", "Thank you. Could you tell us what time check-out is and whether breakfast is included?"]]}, {"title": "Support someone at a running event", "area": "Family and sport · everyday interaction", "context": "You attend a race to cheer on a family member; a visitor asks for practical information.", "prep": ["My son is taking part in the race.", "I am here to cheer him on.", "Could you tell me where the finish line is?"], "turns": [["Are you running today?", "No, I am here to cheer on my son and other family members.", "No I am to cheer my son on yesterday.", "I am not sport.", 0, "Use present simple now: I am here to…", "I am here to cheer on…", "No, I am supporting my family.", "Not today. My son and other family members are taking part, so I have come to cheer them on."], ["Do you enjoy running yourself?", "Yes, I run regularly with a running group.", "Yes I running in every now.", "Yes I am run.", 0, "Use present simple for a regular activity.", "I run regularly…", "Yes, I run regularly.", "Yes, I train regularly, and my coach recently moved me to a more advanced running group because of my progress."], ["Why do you like these events?", "Because I enjoy supporting my family and spending time together.", "Because of I like family.", "Due I am family.", 0, "Because + full clause.", "Because + I…", "I like supporting my family.", "I enjoy the atmosphere and the opportunity to encourage my family while sharing an interest in sport."]]}];
const ORAL_TOPICS = [{"topic": "Why is teamwork important?", "q": "Do you think teamwork is important when supporting families?", "hint": "Opinion: I think teamwork is important. Reason: because different people can share information. Example: In my previous job…", "a2": "Yes, I think teamwork is important because people can help each other. In my previous job, we worked together to find solutions.", "b1": "In my opinion, teamwork is essential when supporting families because people bring different perspectives and experience. For example, in my previous career we discussed situations together to develop suitable action plans. However, it is also important to listen to the family."}, {"topic": "Sport and wellbeing", "q": "Do you think running is a good activity for people of all ages?", "hint": "I think… because… For example, I run regularly… However, everyone should choose a suitable activity.", "a2": "Yes, I think running is good for health. I run regularly and enjoy it. People should choose an activity that suits them.", "b1": "I think regular physical activity is beneficial at many ages because it supports health and wellbeing. For example, my running has improved, and my coach recently moved me into a more advanced group. However, everyone should choose an activity that suits their abilities."}, {"topic": "Travel: nature or cities?", "q": "Do you prefer visiting historical cities or spending time in nature when you travel?", "hint": "I prefer… because… For example… On the other hand…", "a2": "I enjoy both, but I prefer nature because I love walking. I also like visiting historical cities with my husband.", "b1": "I enjoy a combination of both, although I especially appreciate walking in natural surroundings. For example, my travel interests include the landscapes around Mljet and Durmitor, as well as historic places such as Dubrovnik. The balance makes a trip more interesting."}, {"topic": "Listening and empathy", "q": "What is more important when helping someone: listening or giving advice?", "hint": "I think… is more important because… In my previous work… However…", "a2": "I think listening is very important because you need to understand the problem before giving advice.", "b1": "In my view, listening carefully should come first, because it helps us understand a person’s needs without making assumptions. In my previous career, this was essential when working with children and families. Advice is important too, but only after understanding the situation."}, {"topic": "Life after retirement", "q": "Do you think it is important to stay active after retirement?", "hint": "In my opinion… because… I volunteer… I also…", "a2": "Yes, I think staying active is important. I volunteer, walk and run. These activities help me feel good.", "b1": "Yes, I believe it is important to remain engaged and active after retirement. For example, I continue volunteering in youth justice and I enjoy running, travelling and walking. These activities help me maintain social connections and keep learning."}, {"topic": "Privacy and trust", "q": "Why is confidentiality important when working with families?", "hint": "I think… because… For example, private information… We should…", "a2": "Confidentiality is important because people need to trust professionals. We must not share private information.", "b1": "I believe confidentiality is essential because families need to feel that their personal information will be treated respectfully. It also builds trust. In practice, we should explain procedures without discussing individual cases or identifying anyone."}];

let rpIndex=0,rpTurn=0,rpChoice=-1,rpStats={},fullIndex=0,fullStarted=false,oralNotes={};
function persistOral(){try{localStorage.setItem('catherine_final_oral',JSON.stringify({rpStats,oralNotes,progress}));}catch(e){}}
function loadOral(){try{let z=JSON.parse(localStorage.getItem('catherine_final_oral')||'{}');rpStats=z.rpStats||{};oralNotes=z.oralNotes||{};if(z.progress)progress=z.progress;}catch(e){}}
function emitSpeech(text){speak(text)}
function rpRender(){const r=ORAL_ROLEPLAYS[rpIndex],t=r.turns[rpTurn];rpChoice=-1;
$('rpSelect').value=String(rpIndex);
$('rpCard').innerHTML=`<div class="role-head"><div class="kicker">${esc(r.area.toUpperCase())}</div><h3>${esc(r.title)}</h3><p>${esc(r.context)}</p></div><div class="role-main"><div class="role-step">Exchange ${rpTurn+1} of ${r.turns.length}</div><div class="role-bubble"><b>EXAMINER / OTHER PERSON</b>${esc(t[0])}</div><button class="secondary" type="button" data-rp="listen">🔊 Hear their words</button><details class="soft-details"><summary>Vocabulary & sentence starters before answering</summary><ul>${r.prep.map(x=>`<li>${esc(x)} <button type="button" class="secondary" data-say="${esc(x)}">🔊</button></li>`).join('')}</ul></details><h4>Which answer works best?</h4><div class="rp-choices">${t.slice(1,4).map((x,i)=>`<button type="button" class="role-choice" data-rp-choice="${i}">${esc(x)}</button>`).join('')}</div><div id="rpFeedback" aria-live="polite"></div><div class="actions"><button type="button" class="secondary" data-rp="hint">💡 Hint</button><button type="button" class="secondary" data-rp="model">See A2 / B1 models</button><button type="button" class="secondary" data-rp="reveal">Show suggested answer</button></div><div id="rpReveal" hidden></div><div class="role-sentence"><label>Say the answer aloud, then optionally write your own version<textarea rows="3" id="rpOwn" placeholder="Try speaking first. You can use this to note your answer."></textarea></label><button type="button" class="secondary" data-rp="save">Save my words</button></div></div>`;
$('rpNext').disabled=true;$('rpProgress').textContent=`Conversation ${rpIndex+1} / ${ORAL_ROLEPLAYS.length} · Turn ${rpTurn+1} / ${r.turns.length}`;
$('rpOwn').value=oralNotes[`rp${rpIndex}-${rpTurn}`]||'';
}
function rpFeedback(ok,msg){const f=$('rpFeedback');f.className='role-feedback '+(ok?'good':'bad');f.textContent=(ok?'✓ ':'✗ ')+msg}
function rpShow(kind){let t=ORAL_ROLEPLAYS[rpIndex].turns[rpTurn],e=$('rpReveal');e.hidden=false;if(kind==='hint'){e.className='model';e.textContent='HINT · '+t[6];}else if(kind==='model'){e.className='rp-models';e.innerHTML=`<article><h4>A2 · clear</h4><p>${esc(t[7])}</p><button type="button" class="secondary" data-say="${esc(t[7])}">🔊 Listen</button></article><article><h4>B1 · stretch</h4><p>${esc(t[8])}</p><button type="button" class="secondary" data-say="${esc(t[8])}">🔊 Listen</button></article>`;}else{e.className='model';e.textContent='BEST ANSWER · '+t[1+t[4]]+'\n'+t[5];}}
function opRender(){let o=ORAL_TOPICS[+$('opSelect').value];$('opPrompt').innerHTML=`<span class="micro-title">EXAMINER QUESTION</span><h3>${esc(o.q)}</h3><p class="muted">Answer: your opinion → a reason → an example → a balance / contrast.</p>`;$('opReveal').hidden=true;$('opFeedback').textContent='';$('opAnswer').value=oralNotes['topic'+$('opSelect').value]||'';}
function opFeedback(){const s=$('opAnswer').value.trim(),f=$('opFeedback');if(s.length<18){f.className='feedback bad';f.textContent='Add at least one clear opinion and a reason. This is a writing-structure check, not an automatic speaking grade.';return;}let checks=[/(i think|in my opinion|i believe|i prefer|i feel)/i.test(s),/(because|since|one reason|as it)/i.test(s),/(for example|for instance|in my experience|when i|i run|i worked)/i.test(s)];let cnt=checks.filter(Boolean).length;f.className='feedback '+(cnt>=2?'good':'bad');f.textContent=cnt+'/3 helpful building blocks recognised: '+['an opinion','a reason','an example'].filter((_,i)=>!checks[i]).join(', ')+(cnt===3?'. Great structure!':'. Add these to make your answer stronger.');oralNotes['topic'+$('opSelect').value]=s;persistOral()}
const FULL_ORAL=[
 ['Part 1 · Introduction','Could you introduce yourself and tell me what you do now?','Where you live → retired → volunteer role → one interest.','I live in Claye-Souilly. I am retired, but I volunteer as an assessor in youth justice. I enjoy running and travelling with my husband.','I live in Claye-Souilly. In my previous career I worked as a social worker, and I now volunteer as an assessor in youth justice. I also enjoy running, walking in nature and travelling with my husband.'],
 ['Part 1 · Introduction','What did you do before you retired?','Past simple: I worked… My role involved…','I worked as a social worker. I visited families and listened to parents and children.','I worked as a social worker supporting children and families. My role involved home visits, careful listening and working with a team to develop action plans.'],
 ['Part 1 · Follow-up','What do you enjoy doing in your free time?','Present simple → recent achievement → reason.','I enjoy running and walking. My coach moved me to a better running group.','I run regularly, and my coach recently moved me to a more advanced group because of my progress. I also enjoy cheering on my children at running events.'],
 ['Part 2 · Role-play','Visitor: Hello, I have an appointment but I do not know where to go.','Greet → ask for details → offer to check.','Hello. How can I help you? I can check the room for you.','Of course. Could you tell me who you are here to see? I can check your appointment and direct you to the right place.'],
 ['Part 2 · Role-play','Parent: I am worried and I do not know what to do next.','Show empathy → ask a question → suggest a next step.','I understand. Could you explain what is worrying you?','I understand this must be worrying. Could you tell me a little more about the situation so we can discuss possible next steps together?'],
 ['Part 2 · Role-play','Colleague: I disagree with your suggested action plan.','Acknowledge → propose collaboration.','I understand. Let us discuss the options.','I understand your point. Perhaps we could review the alternatives together and focus on the child’s needs before deciding on the next step.'],
 ['Part 3 · Discussion','Why is it important to listen carefully when supporting families?','Opinion → because → work example.','Listening is important because it helps people feel understood.','In my opinion, active listening is essential because it helps us understand individual needs. In my previous career, listening to parents and children was an important part of finding suitable solutions.'],
 ['Part 3 · Discussion','Do you think sport is important as people get older?','Opinion → personal example → balanced conclusion.','Yes, I think sport is important. I run regularly and it helps me feel good.','Yes, I believe physical activity can help people stay healthy and motivated as they get older. My own running has improved over time, although everyone should find an activity that matches their abilities.'],
 ['Part 3 · Discussion','Is teamwork always better than working alone?','Opinion → reason → example → however.','Teamwork is very useful because people can share ideas.','In many situations teamwork is important because professionals can exchange ideas and avoid making decisions in isolation. For example, in social work we developed action plans together. However, some tasks also require independent responsibility.']
];
function fullRender(){const q=FULL_ORAL[fullIndex];$('fullStage').textContent=q[0];$('fullTurn').textContent=(fullIndex+1)+' / '+FULL_ORAL.length;$('fullQuestion').textContent=q[1];$('fullReveal').hidden=true;$('fullAnswer').value=oralNotes['full'+fullIndex]||'';$('fullPrev').disabled=fullIndex===0;$('fullNext').textContent=fullIndex===FULL_ORAL.length-1?'Finish mock ✓':'Next prompt →'}
function track(){const done=Object.values(progress).filter(x=>x.correct).length,attempted=Object.keys(progress).length;const rp=Object.values(rpStats).filter(x=>x===true).length;$('trackingPreview').textContent=`Grammar: ${done} correct / ${attempted} attempted · Role-play responses: ${rp} correct · You can copy the progress row below.`}
function trackingText(){const d=new Date().toLocaleDateString('fr-FR');const correct=Object.values(progress).filter(x=>x.correct).length;return ['Date','Learner','Lesson link','Sections','Activities','Content','Exercise types','Grammar correct','Role-play correct','Skills','Status','Next steps','Trainer notes'].join('\t')+'\n'+[d,'Catherine',$('lessonURL').value,'Introduction / grammar / vocabulary / guided interview / role-plays / opinion / mock','CLOE oral practice','Past/present; professional role; empathy/teamwork; family/sport; polite interaction','Multiple choice; 3-turn dialogues; model comparison; spoken mock',correct,Object.values(rpStats).filter(x=>x).length,'Interaction; fluency; vocabulary; grammatical accuracy','En cours',$('target').value,$('trainerNotes').value].map(x=>String(x).replace(/\t|\n/g,' ')).join('\t')}
function downloadProgress(){let content=trackingText()+'\n\n'+['Personal introduction',introduction(),'','Practice reflection',$('reflection').value,'','Trainer notes',$('trainerNotes').value,'','Saved speaking attempts',...Object.entries(oralNotes).map(([k,v])=>k+': '+v)].join('\n');const blob=new Blob([content],{type:'text/plain;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='Catherine_CLOE_oral_notes_and_tracking.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function oralInit(){loadOral();renderScore();$('rpSelect').innerHTML=ORAL_ROLEPLAYS.map((r,i)=>`<option value="${i}">${i+1}. ${esc(r.title)}</option>`).join('');$('rpSelect').onchange=()=>{rpIndex=+$('rpSelect').value;rpTurn=0;rpRender()};$('rpRestart').onclick=()=>{rpTurn=0;rpRender()};$('rpNext').onclick=()=>{if(rpTurn<ORAL_ROLEPLAYS[rpIndex].turns.length-1)rpTurn++;else{rpTurn=0;rpIndex=(rpIndex+1)%ORAL_ROLEPLAYS.length}rpRender()};$('rpCard').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const r=ORAL_ROLEPLAYS[rpIndex],t=r.turns[rpTurn];if(b.dataset.rpChoice!==undefined){let picked=Number(b.dataset.rpChoice),ok=picked===t[4];rpChoice=picked;document.querySelectorAll('.role-choice').forEach(x=>x.classList.toggle('selected',x===b));rpFeedback(ok,ok?t[5]:'Not quite. '+t[6]+' Try another answer.');rpStats[rpIndex+'-'+rpTurn]=ok;persistOral();track();if(ok)$('rpNext').disabled=false;}if(b.dataset.rp==='listen')emitSpeech(t[0]);if(b.dataset.rp==='hint'){if($('rpLevel').value==='guided')rpShow('hint');else{let f=$('rpFeedback');f.className='role-feedback bad';f.textContent='Independent mode: try a response first, then reveal the model.'}}if(b.dataset.rp==='model'){if($('rpLevel').value==='guided'||rpChoice>=0)rpShow('model');else rpFeedback(false,'Answer once before revealing the model in independent mode.')}if(b.dataset.rp==='reveal'){if($('rpLevel').value==='guided'||rpChoice>=0)rpShow('reveal');else rpFeedback(false,'Try an answer first.')}if(b.dataset.rp==='save'){oralNotes['rp'+rpIndex+'-'+rpTurn]=$('rpOwn').value;persistOral();note('Your notes were saved on this device.')}});rpRender();
$('opSelect').innerHTML=ORAL_TOPICS.map((o,i)=>`<option value="${i}">${i+1}. ${esc(o.topic)}</option>`).join('');$('opSelect').onchange=opRender;opRender();$('opHint').onclick=()=>{let o=ORAL_TOPICS[+$('opSelect').value];$('opReveal').hidden=false;$('opReveal').textContent=o.hint};$('opA2').onclick=()=>{$('opReveal').hidden=false;$('opReveal').textContent='A2 MODEL\n'+ORAL_TOPICS[+$('opSelect').value].a2};$('opB1').onclick=()=>{$('opReveal').hidden=false;$('opReveal').textContent='B1 MODEL\n'+ORAL_TOPICS[+$('opSelect').value].b1};$('opHear').onclick=()=>emitSpeech(ORAL_TOPICS[+$('opSelect').value].q);$('opCheck').onclick=opFeedback;
$('opChoices').onclick=e=>{const b=e.target.closest('button[data-ans]');if(!b)return;const ok=b.dataset.ans==='right',f=$('opChoiceFeedback');f.className='feedback '+(ok?'good':'bad');f.textContent=ok?'✓ Correct! Because is followed by a clause: people can support each other.':'✗ Not quite. Because of must be followed by a noun, not a full clause.'};
$('mockFullStart').onclick=()=>{fullIndex=0;$('fullMock').hidden=false;fullRender();$('fullMock').scrollIntoView({behavior:'smooth',block:'center'})};$('fullPrev').onclick=()=>{oralNotes['full'+fullIndex]=$('fullAnswer').value;persistOral();fullIndex=Math.max(0,fullIndex-1);fullRender()};$('fullNext').onclick=()=>{oralNotes['full'+fullIndex]=$('fullAnswer').value;persistOral();if(fullIndex<FULL_ORAL.length-1){fullIndex++;fullRender()}else{note('Full oral rehearsal complete! Review your progress below.');$('review').scrollIntoView({behavior:'smooth'})}};$('fullHear').onclick=()=>emitSpeech(FULL_ORAL[fullIndex][1]);$('fullStarter').onclick=()=>{$('fullReveal').hidden=false;$('fullReveal').textContent='STARTER · '+FULL_ORAL[fullIndex][2]};$('fullA2').onclick=()=>{$('fullReveal').hidden=false;$('fullReveal').textContent='A2 MODEL\n'+FULL_ORAL[fullIndex][3]};$('fullB1').onclick=()=>{$('fullReveal').hidden=false;$('fullReveal').textContent='B1 MODEL\n'+FULL_ORAL[fullIndex][4]};
$('printPage').onclick=()=>window.print();$('copyTracking').onclick=async()=>{try{await navigator.clipboard.writeText(trackingText());note('Centre tracking copied.')}catch(e){const t=document.createElement('textarea');t.value=trackingText();document.body.append(t);t.select();document.execCommand('copy');t.remove();note('Centre tracking copied.')}};
$('exportNotes').onclick=downloadProgress;$('downloadTop').onclick=downloadProgress;
['trainerNotes','lessonURL','reflection','target'].forEach(id=>{$(id).value=oralNotes[id]||'';$(id).addEventListener('input',()=>{oralNotes[id]=$(id).value;persistOral();})});
document.addEventListener('click',e=>{const b=e.target.closest('button[data-say]');if(b)emitSpeech(b.dataset.say)});
// Preserve the original instant-answer scoring, now with local progress.
document.addEventListener('click',e=>{const b=e.target.closest('.exercise button[data-choice],.exercise button[data-reset]');if(b){setTimeout(()=>{persistOral();track()},0)}});
$('resetAll').addEventListener('click',()=>{rpStats={};persistOral();track()});track();}
document.addEventListener('DOMContentLoaded',oralInit);
